cat > $TMPDIR/check.mjs <<'EOF'
import { chromium } from '@playwright/test';
const b = await chromium.launch(); const p = await b.newPage();
const errs=[]; p.on('console',m=>m.type()==='error'&&errs.push(m.text())); p.on('requestfailed',r=>errs.push('FAIL '+r.url()));
p.on('response',r=>r.status()>=400&&errs.push(r.status()+' '+r.url()));
for (const pg of ['index','products','pricing','orders','about','contact']) {
  await p.goto(`http://127.0.0.1:${process.env.PORT}/${pg}.html`); await p.evaluate(()=>document.fonts.ready);
  const r = await p.evaluate(()=>({loaded:document.fonts.check("16px 'Acme Sans'"), status:[...document.fonts].map(f=>f.status).join(','), sheets:[...document.styleSheets].map(s=>s.cssRules.length).join('/')}));
  console.log(pg, JSON.stringify(r));
}
console.log('errors:', errs); await b.close();
EOF
cp $TMPDIR/check.mjs ./.check.mjs && node ./.check.mjs; rm ./.check.mjs

